import java.io.*;
import java.util.*;

public class TaskD {
    boolean eof;
    BufferedReader reader;
    StringTokenizer tokenizer;
    PrintWriter writer;

    public static void main(String[] args) throws IOException {
        TaskD task = new TaskD();
        task.execute();
    }

    private String readToken() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (Exception e) {
                eof = true;
                return "-1";
            }
        }
        return tokenizer.nextToken();
    }

    private long readLong() {
        return Long.parseLong(readToken());
    }

    private void execute() throws IOException {
        InputStream input = System.in;
        PrintStream output = System.out;
        try {
            File f = new File("a.in");
            if (f.exists() && f.canRead()) {
                input = new FileInputStream(f);
                output = new PrintStream("a.out");
            }
        } catch (Throwable e) {
        }
        reader = new BufferedReader(new InputStreamReader(input));
        writer = new PrintWriter(output);
        solve();
        reader.close();
        writer.close();
    }

    private long largestEven(long value) {
        return value - value % 2;
    }

    private long compute(long a, long b) {
        if (a > b) {
            long temp = a;
            a = b;
            b = temp;
        }
        if (a > 3) {
            return largestEven(a * b);
        }
        long s = b - b % 6;
        int o = (int) (b % 6);
        long h = 0;
        switch ((int) a) {
            case 1:
                switch (o) {
                    case 4: h = 2; break;
                    case 5: h = 4; break;
                    default: h = 0; break;
                }
                break;
            case 2:
                switch (o) {
                    case 3: h = 4; break;
                    case 4: h = 8; break;
                    case 5: h = 10; break;
                    default: h = 0; break;
                }
                break;
            case 3:
                switch (o) {
                    case 2: h = 4; break;
                    case 3: h = 8; break;
                    case 4: h = 12; break;
                    case 5: h = 14; break;
                    default: h = 0; break;
                }
                break;
            default:
                h = 0;
                break;
        }
        if (a + b > 9 && a > 1) {
            return largestEven(a * b);
        }
        return s * a + h;
    }

    private void solve() {
        long n = readLong();
        long m = readLong();
        writer.print(compute(n, m));
    }
}
